const Button = ({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'danger' }) => {
  const variants = {
    primary: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-[0_8px_18px_hsl(var(--primary)/.15)] hover:-translate-y-0.5',
    secondary: 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--primary))] hover:border-[hsl(var(--primary)/.35)] hover:bg-[hsl(var(--muted))]',
    ghost: 'text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--primary))]',
    danger: 'bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))] hover:-translate-y-0.5',
  };
  return <button className={`inline-flex items-center justify-center rounded-xl px-4 py-2.5 text-sm font-bold transition-all ${variants[variant]} ${className}`} {...props}>{children}</button>;
};

const StatusPill = ({ status }: { status: string }) => {
  const style = status === 'Completed' || status === 'Approved' ? 'bg-[hsl(var(--chart-4)/.13)] text-[hsl(var(--chart-4))]' : status === 'Need attention' || status === 'Documents required' || status === 'Open' ? 'bg-[hsl(var(--accent)/.13)] text-[hsl(var(--accent))]' : status === 'Inspection scheduled' || status === 'In progress' ? 'bg-[hsl(var(--secondary)/.35)] text-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]';
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold ${style}`} data-testid={`status-${status.toLowerCase().replaceAll(' ', '-')}`}>{status === 'Completed' || status === 'Approved' ? <Check className="h-3 w-3" /> : null}{status}</span>;
};

