    saveLocal('user-name', shown ? shown.charAt(0).toUpperCase() + shown.slice(1) : '');
    if (phone) saveLocal('user-phone', phone);
    if (blankProfile) saveLocal('profile', { ...DEMO_PROFILE, companyName: '', businessType: '', district: '' });
    else if (!localStorage.getItem('bizvia:profile')) saveLocal('profile', DEMO_PROFILE);
    startDemoSession('business', email);
    setLocation(destination);
