export function Onboarding() {
  const [, setLocation] = useLocation();
  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<BusinessProfile>(() => readLocal('profile', DEMO_PROFILE));
  const steps = ['Business', 'Location', 'Project', 'Review'];
  const update = (key: keyof BusinessProfile, value: string | number) => setProfile((current) => ({ ...current, [key]: value }));
  const finish = () => { saveLocal('profile', profile); setLocation('/roadmap'); };
  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]"><header className="mx-auto flex max-w-6xl items-center justify-between px-5 py-6 lg:px-8"><Logo /><button className="text-xs font-bold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" onClick={() => setLocation('/dashboard')} data-testid="button-skip-onboarding">Skip for now</button></header><main className="mx-auto max-w-4xl px-5 pb-16 pt-5 lg:px-8"><div className="mx-auto max-w-xl text-center"><p className="eyebrow text-[hsl(var(--accent))]">Let’s map your route</p><h1 className="display mt-4 text-4xl font-extrabold tracking-[-.04em] text-[hsl(var(--primary))]">Tell us about the project.</h1><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">We’ll use these details to shape a practical approval roadmap. You can change them later.</p></div><div className="mx-auto mt-10 flex max-w-2xl items-center justify-between">{steps.map((item, index) => <div key={item} className="flex items-center"><div className={`grid h-9 w-9 place-items-center rounded-full text-xs font-bold ${step > index + 1 ? 'bg-[hsl(var(--chart-4))] text-white' : step === index + 1 ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`}>{step > index + 1 ? <Check className="h-4 w-4" /> : index + 1}</div>{index < steps.length - 1 && <div className={`mx-2 h-px w-9 sm:mx-5 sm:w-20 ${step > index + 1 ? 'bg-[hsl(var(--chart-4))]' : 'bg-[hsl(var(--border))]'}`} />}</div>)}</div><div className="mx-auto mt-10 max-w-2xl rounded-[24px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 shadow-[0_16px_40px_hsl(var(--foreground)/.05)] sm:p-8">{step === 1 && <WizardStep title="Your business" copy="Start with the basics that identify your business." icon={<Factory />}><Field label="Company name" value={profile.companyName} onChange={(value) => update('companyName', value)} testId="input-company-name" /><Field label="What are you building?" value={profile.businessType} onChange={(value) => update('businessType', value)} testId="input-business-type" /></WizardStep>}{step === 2 && <WizardStep title="Where will it operate?" copy="Location determines which departments and local permissions come into view." icon={<MapPin />}><SelectField label="State" value={profile.state} onChange={(value) => update('state', value)} options={['Maharashtra', 'Gujarat', 'Karnataka', 'Tamil Nadu']} testId="select-state" /><Field label="District" value={profile.district} onChange={(value) => update('district', value)} testId="input-district" /><SelectField label="Location type" value={profile.locationType} onChange={(value) => update('locationType', value)} options={['Industrial Area', 'Urban Area', 'Rural Area', 'Special Economic Zone']} testId="select-location-type" /></WizardStep>}{step === 3 && <WizardStep title="Project snapshot" copy="A quick picture helps us sequence your approvals sensibly." icon={<IndianRupee />}><SelectField label="Investment" value={profile.investment} onChange={(value) => update('investment', value)} options={['₹10 lakh', '₹25 lakh', '₹50 lakh', '₹1 crore', '₹5 crore']} testId="select-investment" /><Field label="Expected employees" value={String(profile.employees)} onChange={(value) => update('employees', Number(value))} type="number" testId="input-employees" /><SelectField label="Project stage" value={profile.projectStage} onChange={(value) => update('projectStage', value as BusinessProfile['projectStage'])} options={['Pre-construction', 'Construction', 'Operational']} testId="select-project-stage" /></WizardStep>}{step === 4 && <div><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[hsl(var(--secondary)/.35)] text-[hsl(var(--primary))]"><BadgeCheck /></span><h2 className="display mt-5 text-2xl font-extrabold text-[hsl(var(--primary))]">Ready to map your route?</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Here’s what we’ll use for your first roadmap.</p><div className="mt-6 grid gap-3 sm:grid-cols-2">{Object.entries(profile).map(([key, value]) => <div key={key} className="rounded-xl bg-[hsl(var(--muted)/.62)] p-3"><p className="eyebrow text-[hsl(var(--muted-foreground))]">{key.replace(/([A-Z])/g, ' $1')}</p><p className="mt-1 text-sm font-bold text-[hsl(var(--primary))]">{String(value)}</p></div>)}</div><p className="mt-6 flex gap-2 rounded-xl bg-[hsl(var(--primary)/.05)] p-3 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><Info className="mt-0.5 h-4 w-4 shrink-0 text-[hsl(var(--primary))]" /> Requirements shown in this prototype are simulated demo data. Production would connect to verified regulatory sources.</p></div>}<div className="mt-8 flex items-center justify-between border-t border-[hsl(var(--border))] pt-5"><Button variant="ghost" disabled={step === 1} onClick={() => setStep((value) => value - 1)} data-testid="button-onboarding-back"><ArrowLeft className="mr-2 h-4 w-4" /> Back</Button>{step < 4 ? <Button onClick={() => setStep((value) => value + 1)} data-testid="button-onboarding-continue">Continue <ArrowRight className="ml-2 h-4 w-4" /></Button> : <Button onClick={finish} data-testid="button-onboarding-finish">Build my roadmap <Sparkles className="ml-2 h-4 w-4" /></Button>}</div></div></main></div>;
}
function WizardStep({ title, copy, icon, children }: { title: string; copy: string; icon: React.ReactNode; children: React.ReactNode }) { return <div><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[hsl(var(--secondary)/.35)] text-[hsl(var(--primary))]">{icon}</span><h2 className="display mt-5 text-2xl font-extrabold text-[hsl(var(--primary))]">{title}</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{copy}</p><div className="mt-7 space-y-5">{children}</div></div>; }
function Field({ label, value, onChange, type = 'text', testId }: { label: string; value: string; onChange: (value: string) => void; type?: string; testId: string }) { return <label className="block text-sm font-bold text-[hsl(var(--primary))]">{label}<input type={type} value={value} onChange={(event) => onChange(event.target.value)} className="mt-2 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-4 py-3 text-sm outline-none focus:border-[hsl(var(--primary))] focus:ring-4 focus:ring-[hsl(var(--primary)/.08)]" data-testid={testId} /></label>; }
function SelectField({ label, value, onChange, options, testId }: { label: string; value: string; onChange: (value: string) => void; options: string[]; testId: string }) { return <label className="block text-sm font-bold text-[hsl(var(--primary))]">{label}<div className="relative mt-2"><select value={value} onChange={(event) => onChange(event.target.value)} className="w-full appearance-none rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-4 py-3 text-sm outline-none focus:border-[hsl(var(--primary))] focus:ring-4 focus:ring-[hsl(var(--primary)/.08)]" data-testid={testId}>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select><ChevronDown className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /></div></label>; }

export function Dashboard() {
  const [, setLocation] = useLocation();
  const [toast, setToast] = useState(true);
  return <AppShell title="Overview" eyebrow="Your business control room"><div className="rise-in"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm font-medium text-[hsl(var(--muted-foreground))]">Tuesday, 15 September 2026</p><h2 className="display mt-2 text-3xl font-extrabold tracking-[-.04em] text-[hsl(var(--primary))]">Good morning{readLocal('user-name', '') ? `, ${readLocal('user-name', '')}` : ''}</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Your route to opening {readLocal<{ companyName?: string }>('profile', {}).companyName || 'your business'} is taking shape.</p></div><Button variant="secondary" onClick={() => setLocation('/roadmap')} data-testid="button-dashboard-roadmap">View full roadmap <ArrowRight className="ml-2 h-4 w-4" /></Button></div><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Approvals identified" value="17" note="across 4 stages" icon={<RouteIcon />} /><Stat label="Completed" value="8" note="47% of your route" icon={<CheckCircle2 />} positive /><Stat label="Need attention" value="3" note="one action due soon" icon={<CircleAlert />} warn /><Stat label="Project progress" value="72%" note="on track for Sep" icon={<ArrowDownRight />} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><div className="space-y-6"><section className="rounded-2xl border border-[hsl(var(--accent)/.25)] bg-[hsl(var(--accent)/.07)] p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div className="flex gap-4"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><CircleAlert className="h-5 w-5" /></span><div><p className="eyebrow text-[hsl(var(--accent))]">Action required</p><h3 className="display mt-2 text-lg font-extrabold text-[hsl(var(--primary))]">Respond to Factory Licence query</h3><p className="mt-1 max-w-lg text-sm leading-6 text-[hsl(var(--muted-foreground))]">The Industries Department has asked for clarification regarding your factory layout.</p></div></div><span className="shrink-0 rounded-full bg-[hsl(var(--card))] px-3 py-1 text-xs font-bold text-[hsl(var(--accent))]">Due in 2 days</span></div><div className="mt-5 flex flex-wrap gap-3"><Button variant="danger" onClick={() => setLocation('/tracking/BE-FAC-2026-001')} data-testid="button-respond-query">Review and respond <ArrowRight className="ml-2 h-4 w-4" /></Button><button className="px-2 text-xs font-bold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" onClick={() => setToast(false)} data-testid="button-dismiss-action">Dismiss for now</button></div></section><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Keep moving</p><h3 className="display mt-2 text-xl font-extrabold text-[hsl(var(--primary))]">Your applications</h3></div><Link href="/roadmap" className="text-xs font-bold text-[hsl(var(--primary))]" data-testid="link-applications-roadmap">See all <ArrowRight className="ml-1 inline h-3 w-3" /></Link></div><div className="mt-5 divide-y divide-[hsl(var(--border))]">{APPLICATIONS.map((application) => <button key={application.id} className="flex w-full items-center gap-3 py-4 text-left transition-colors hover:bg-[hsl(var(--muted)/.4)] sm:px-2" onClick={() => setLocation(application.id === 'BE-FAC-2026-001' ? `/tracking/${application.id}` : '/roadmap')} data-testid={`button-application-${application.id}`}><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[hsl(var(--muted))] text-[hsl(var(--primary))]">{application.name === 'Fire NOC' ? <Flame className="h-4 w-4" /> : <FileCheck2 className="h-4 w-4" />}</span><span className="min-w-0 flex-1"><span className="block text-sm font-bold text-[hsl(var(--primary))]">{application.name}</span><span className="mt-1 block truncate text-xs text-[hsl(var(--muted-foreground))]">{application.department} · {application.id}</span></span><StatusPill status={application.status} /><ChevronRight className="h-4 w-4 text-[hsl(var(--muted-foreground))]" /></button>)}</div></section></div><div className="space-y-6"><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><h3 className="display text-lg font-extrabold text-[hsl(var(--primary))]">Upcoming</h3><Clock3 className="h-4 w-4 text-[hsl(var(--muted-foreground))]" /></div><div className="mt-5 space-y-4"><div className="flex gap-3"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[hsl(var(--accent))]" /><div><p className="text-sm font-bold text-[hsl(var(--primary))]">Factory premises inspection</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">28 September 2026 · Pollution Consent</p></div></div><div className="flex gap-3"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[hsl(var(--secondary))]" /><div><p className="text-sm font-bold text-[hsl(var(--primary))]">Building plan response</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">05 October 2026 · Town Planning</p></div></div></div></section><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-start justify-between"><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Explore support</p><h3 className="display mt-2 text-lg font-extrabold text-[hsl(var(--primary))]">Maharashtra MSME Support</h3></div><Sparkles className="h-5 w-5 text-[hsl(var(--accent))]" /></div><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">A state program that may help with eligible investment and employment costs.</p><span className="mt-4 inline-flex rounded-full bg-[hsl(var(--chart-4)/.12)] px-2.5 py-1 text-[11px] font-bold text-[hsl(var(--chart-4))]">Potentially eligible</span></section></div></div></div>{toast && <div className="fixed bottom-5 right-5 z-30 flex max-w-sm items-start gap-3 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 shadow-[0_16px_40px_hsl(var(--foreground)/.15)] rise-in"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[hsl(var(--secondary)/.35)] text-[hsl(var(--primary))]"><BellIcon /></span><div><p className="text-sm font-bold text-[hsl(var(--primary))]">Your roadmap is ready</p><p className="mt-1 text-xs leading-5 text-[hsl(var(--muted-foreground))]">We found 17 approvals for Acme Foods.</p></div><button className="ml-2 text-[hsl(var(--muted-foreground))]" onClick={() => setToast(false)} data-testid="button-close-toast"><X className="h-4 w-4" /></button></div>}</AppShell>;
}
function Stat({ label, value, note, icon, positive = false, warn = false }: { label: string; value: string; note: string; icon: React.ReactNode; positive?: boolean; warn?: boolean }) { return <div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><p className="text-xs font-bold text-[hsl(var(--muted-foreground))]">{label}</p><span className={`grid h-8 w-8 place-items-center rounded-lg ${warn ? 'bg-[hsl(var(--accent)/.12)] text-[hsl(var(--accent))]' : positive ? 'bg-[hsl(var(--chart-4)/.12)] text-[hsl(var(--chart-4))]' : 'bg-[hsl(var(--secondary)/.3)] text-[hsl(var(--primary))]'}`}>{icon}</span></div><p className="display mt-4 text-3xl font-extrabold text-[hsl(var(--primary))]">{value}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{note}</p></div>; }
const RouteIcon = () => <Route className="h-4 w-4" />;
const BellIcon = () => <Bell className="h-4 w-4" />;

export function Roadmap() {
  const [, setLocation] = useLocation();
  const groups = ['Planning', 'Construction', 'Operations', 'Renewals'] as const;
  return <AppShell title="Approval Roadmap" eyebrow="17 approvals identified"><div className="rise-in"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="text-sm text-[hsl(var(--muted-foreground))]">For Acme Foods Pvt. Ltd. · Food Processing Plant</p><h2 className="display mt-2 text-3xl font-extrabold tracking-[-.04em] text-[hsl(var(--primary))]">The full route, at a glance.</h2></div><Button variant="secondary" onClick={() => setLocation('/dashboard')} data-testid="button-roadmap-dashboard"><LayoutDashboard className="mr-2 h-4 w-4" /> Back to overview</Button></div><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><RoadmapSummary label="17 Approvals Identified" value="17" color="primary" /><RoadmapSummary label="8 Completed" value="8" color="green" /><RoadmapSummary label="3 Need Attention" value="3" color="accent" /><RoadmapSummary label="72% Project Progress" value="72%" color="gold" /></div><div className="mt-9 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Project route</p><h3 className="display mt-2 text-xl font-extrabold text-[hsl(var(--primary))]">From site selection to renewal</h3></div><p className="text-xs text-[hsl(var(--muted-foreground))]">72% overall progress</p></div><div className="mt-5 h-3 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className="h-full w-[72%] rounded-full bg-[hsl(var(--secondary))]" /></div></div><div className="mt-9 space-y-10">{groups.map((group) => <section key={group}><div className="mb-4 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[hsl(var(--primary))] text-xs font-bold text-[hsl(var(--primary-foreground))]">{groups.indexOf(group) + 1}</span><div><p className="eyebrow text-[hsl(var(--accent))]">{group}</p><h3 className="display text-xl font-extrabold text-[hsl(var(--primary))]">{group === 'Planning' ? 'Plan with confidence' : group === 'Construction' ? 'Build without blockers' : group === 'Operations' ? 'Open the doors well-prepared' : 'Keep compliance alive'}</h3></div></div><div className="grid gap-3 lg:grid-cols-2">{APPROVALS.filter((approval) => approval.stage === group).map((approval) => <ApprovalCard key={approval.id} approval={approval} onClick={() => approval.id === 'factory' ? setLocation('/application/BE-FAC-2026-001') : undefined} />)}</div></section>)}</div><p className="mt-12 flex items-start gap-2 rounded-xl bg-[hsl(var(--muted)/.6)] p-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><Info className="mt-0.5 h-4 w-4 shrink-0 text-[hsl(var(--primary))]" /> Approval requirements use simulated demo data. In production, BizVia would connect each requirement and status to verified regulatory sources.</p></div></AppShell>;
}
function RoadmapSummary({ label, value, color }: { label: string; value: string; color: string }) { const styles: Record<string, string> = { primary: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]', green: 'bg-[hsl(var(--chart-4)/.12)] text-[hsl(var(--chart-4))]', accent: 'bg-[hsl(var(--accent)/.12)] text-[hsl(var(--accent))]', gold: 'bg-[hsl(var(--secondary)/.3)] text-[hsl(var(--primary))]' }; return <div className={`rounded-2xl p-5 ${styles[color]}`}><p className="text-xs font-bold opacity-75">{label}</p><p className="display mt-3 text-3xl font-extrabold">{value}</p></div>; }
function ApprovalCard({ approval, onClick }: { approval: Approval; onClick: () => void }) { return <button className={`group rounded-2xl border bg-[hsl(var(--card))] p-4 text-left transition-all hover:-translate-y-0.5 hover:shadow-lg ${approval.status === 'Need attention' ? 'border-[hsl(var(--accent)/.42)]' : 'border-[hsl(var(--border))]'}`} onClick={onClick} data-testid={`card-approval-${approval.id}`}><div className="flex items-start gap-3"><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${approval.status === 'Completed' ? 'bg-[hsl(var(--chart-4)/.12)] text-[hsl(var(--chart-4))]' : approval.status === 'Need attention' ? 'bg-[hsl(var(--accent)/.12)] text-[hsl(var(--accent))]' : 'bg-[hsl(var(--secondary)/.25)] text-[hsl(var(--primary))]'}`}>{approval.status === 'Completed' ? <CheckCircle2 className="h-5 w-5" /> : approval.status === 'Need attention' ? <CircleAlert className="h-5 w-5" /> : <FileText className="h-5 w-5" />}</span><span className="min-w-0 flex-1"><span className="flex items-start justify-between gap-2"><span className="text-sm font-bold text-[hsl(var(--primary))]">{approval.name}</span><ChevronRight className="h-4 w-4 shrink-0 text-[hsl(var(--muted-foreground))] transition-transform group-hover:translate-x-1" /></span><span className="mt-1 block text-xs text-[hsl(var(--muted-foreground))]">{approval.department}</span></span></div><div className="mt-4 flex items-center justify-between"><StatusPill status={approval.status} /><span className="text-[11px] font-bold text-[hsl(var(--muted-foreground))]">{approval.documentsReady}/{approval.documentsTotal} docs ready</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${approval.status === 'Completed' ? 'bg-[hsl(var(--chart-4))]' : approval.status === 'Need attention' ? 'bg-[hsl(var(--accent))]' : 'bg-[hsl(var(--secondary))]'}`} style={{ width: `${approval.readiness}%` }} /></div>{approval.nextStep && <p className="mt-3 text-xs font-semibold text-[hsl(var(--accent))]">Next: {approval.nextStep}</p>}</button>; }

export function Application() {
  const [, setLocation] = useLocation();
  const [uploaded, setUploaded] = useState(() => readLocal('factory-layout-uploaded', false));
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [search, setSearch] = useState('');
  const filteredDocs = useMemo(() => DOCUMENTS.filter((doc) => doc.name.toLowerCase().includes(search.toLowerCase())), [search]);
  const handleUpload = (file?: File) => {
    setUploading(true);
    let value = 0;
    const timer = window.setInterval(() => { value += 20; setProgress(value); if (value >= 100) { window.clearInterval(timer); setUploading(false); setUploaded(true); saveLocal('factory-layout-uploaded', true); } }, 180);
    void file;
  };
  return <AppShell title="Factory Licence" eyebrow="Application · BE-FAC-2026-001"><div className="rise-in"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><button className="mb-4 flex items-center text-xs font-bold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" onClick={() => setLocation('/roadmap')} data-testid="button-application-back"><ArrowLeft className="mr-1.5 h-3.5 w-3.5" /> Back to roadmap</button><div className="flex items-center gap-3"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><Factory /></span><div><p className="eyebrow text-[hsl(var(--accent))]">BE-FAC-2026-001</p><h2 className="display mt-1 text-3xl font-extrabold tracking-[-.04em] text-[hsl(var(--primary))]">Factory Licence</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Industries Department</p></div></div></div><StatusPill status="Documents required" /></div><div className="mt-8 grid gap-6 xl:grid-cols-[1fr_.65fr]"><div className="space-y-6"><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Application readiness</p><h3 className="display mt-2 text-xl font-extrabold text-[hsl(var(--primary))]">{uploaded ? '8/8 documents ready' : '7/8 documents ready'}</h3></div><span className="display text-2xl font-extrabold text-[hsl(var(--primary))]">{uploaded ? '100%' : '87%'}</span></div><div className="mt-5 h-3 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--secondary))] transition-all" style={{ width: uploaded ? '100%' : '87%' }} /></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Detail label="Deadline" value="28 Sep 2026" icon={<Clock3 />} /><Detail label="Next step" value={uploaded ? 'Ready for submission' : 'Upload Factory Layout'} icon={<Upload />} accent /></div></section><section className="rounded-2xl border border-[hsl(var(--accent)/.25)] bg-[hsl(var(--accent)/.06)] p-5 sm:p-7"><div className="flex gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><CircleAlert className="h-5 w-5" /></span><div><p className="eyebrow text-[hsl(var(--accent))]">One document is holding this up</p><h3 className="display mt-2 text-lg font-extrabold text-[hsl(var(--primary))]">Upload Factory Layout</h3><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">A PDF, JPG, or PNG showing the proposed processing line, storage area, and safe separation.</p></div></div>{uploaded ? <div className="mt-5 flex items-center gap-3 rounded-xl bg-[hsl(var(--card))] p-3 text-sm font-bold text-[hsl(var(--chart-4))]"><CheckCircle2 className="h-5 w-5" /> Factory Layout.pdf uploaded and ready</div> : <div className="mt-5 rounded-2xl border-2 border-dashed border-[hsl(var(--accent)/.4)] bg-[hsl(var(--card)/.55)] p-6 text-center"><input type="file" accept=".pdf,.jpg,.jpeg,.png" className="hidden" id="layout-upload" onChange={(event) => handleUpload(event.target.files?.[0])} data-testid="input-factory-layout" /><label htmlFor="layout-upload" className="mx-auto flex cursor-pointer flex-col items-center"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[hsl(var(--secondary)/.3)] text-[hsl(var(--primary))]"><CloudUpload /></span><span className="mt-3 text-sm font-bold text-[hsl(var(--primary))]">{uploading ? `Uploading... ${progress}%` : 'Choose a file to upload'}</span><span className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">PDF, JPG, or PNG · max 10 MB</span></label>{uploading && <div className="mx-auto mt-5 h-2 max-w-sm overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--accent))] transition-all" style={{ width: `${progress}%` }} /></div>}</div>}</section><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Document Vault</p><h3 className="display mt-2 text-xl font-extrabold text-[hsl(var(--primary))]">Reuse what is ready</h3></div><FolderSearch className="h-5 w-5 text-[hsl(var(--muted-foreground))]" /></div><div className="relative mt-5"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search documents" className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] py-3 pl-10 pr-4 text-sm outline-none focus:border-[hsl(var(--primary))]" data-testid="input-document-search" /></div><div className="mt-3 divide-y divide-[hsl(var(--border))]">{filteredDocs.map((doc) => <div key={doc.id} className="flex items-center gap-3 py-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><FileText className="h-4 w-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-[hsl(var(--primary))]">{doc.name}</p><p className="mt-0.5 text-[11px] text-[hsl(var(--muted-foreground))]">{doc.type} · uploaded {doc.uploadedAt}</p></div>{doc.verified && <span className="text-[hsl(var(--chart-4))]" title="Verified"><BadgeCheck className="h-4 w-4" /></span>}<button className="rounded-lg px-2.5 py-1.5 text-[11px] font-bold text-[hsl(var(--primary))] hover:bg-[hsl(var(--muted))]" onClick={() => alert(`${doc.name} selected for reuse.`)} data-testid={`button-reuse-${doc.id}`}>Reuse</button></div>)}</div></section></div><aside className="space-y-6"><ApplicationProgress uploaded={uploaded} /><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><p className="eyebrow text-[hsl(var(--muted-foreground))]">Application details</p><div className="mt-4 space-y-4"><Detail label="Reference" value="BE-FAC-2026-001" /><Detail label="Submitted" value="24 Aug 2026" /><Detail label="Department" value="Industries Department" /></div></div></aside></div></div></AppShell>;
}
function Detail({ label, value, icon, accent = false }: { label: string; value: string; icon?: React.ReactNode; accent?: boolean }) { return <div className="flex items-start gap-3">{icon && <span className={`mt-0.5 ${accent ? 'text-[hsl(var(--accent))]' : 'text-[hsl(var(--muted-foreground))]'}`}>{icon}</span>}<div><p className="text-[11px] font-bold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">{label}</p><p className={`mt-1 text-sm font-bold ${accent ? 'text-[hsl(var(--accent))]' : 'text-[hsl(var(--primary))]'}`}>{value}</p></div></div>; }
function ApplicationProgress({ uploaded }: { uploaded: boolean }) { return <div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--primary))] p-5 text-[hsl(var(--primary-foreground))]"><p className="eyebrow opacity-60">Journey</p><h3 className="display mt-2 text-xl font-extrabold">Document readiness</h3><div className="mt-6 space-y-5">{[['Application created', true], ['Documents collected', true], ['Final document', uploaded], ['Ready to submit', uploaded]].map(([label, done], index) => <div className="flex gap-3" key={String(label)}><div className={`relative grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-bold ${done ? 'bg-[hsl(var(--secondary))] text-[hsl(var(--foreground))]' : 'border border-[hsl(var(--primary-foreground)/.3)] text-[hsl(var(--primary-foreground)/.6)]'}`}>{done ? <Check className="h-3.5 w-3.5" /> : index + 1}{index < 3 && <span className={`absolute left-1/2 top-7 h-5 w-px ${done ? 'bg-[hsl(var(--secondary)/.7)]' : 'bg-[hsl(var(--primary-foreground)/.2)]'}`} />}</div><p className={`pt-1 text-sm font-semibold ${done ? '' : 'opacity-60'}`}>{String(label)}</p></div>)}</div></div>; }

export function Tracking() {
  const [, setLocation] = useLocation();
  const [query, setQuery] = useState(() => readLocal('query', DEMO_QUERY));
  const [response, setResponse] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [fileName, setFileName] = useState('');
  const [decision, setDecision] = useState(() => readLocal('decision', ''));
const [alertText, setAlertText] = useState('');
useEffect(() => {
  const sync = (event: StorageEvent) => {
    if (event.key === 'bizvia:query') {
      const next = readLocal('query', DEMO_QUERY);
      setQuery(next);
      if (event.newValue && next.status === 'Open') setAlertText('New query from the Industries Department');
    }
    if (event.key === 'bizvia:decision') setDecision(readLocal('decision', ''));
  };
  window.addEventListener('storage', sync);
  return () => window.removeEventListener('storage', sync);
}, []);
  const submitResponse = () => { if (!response.trim()) return; const next = { ...query, status: 'Responded' as const, response }; setQuery(next); saveLocal('query', next); setShowModal(false); };
  return <AppShell title="Application tracking" eyebrow="Factory Licence · BE-FAC-2026-001"><div className="rise-in">{alertText && <div className="mb-5 flex items-center justify-between rounded-xl bg-[hsl(var(--accent))] px-4 py-3 text-sm font-bold text-[hsl(var(--accent-foreground))]"><span>🔔 {alertText}</span><button onClick={() => setAlertText('')}>✕</button></div>}{decision === 'Approved' && <div className="mb-5 rounded-xl bg-[hsl(var(--chart-4))] px-4 py-3 text-sm font-bold text-white">✅ Your Factory Licence has been approved</div>}<button className="mb-4 flex items-center text-xs font-bold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" onClick={() => setLocation('/dashboard')} data-testid="button-tracking-back"><ArrowLeft className="mr-1.5 h-3.5 w-3.5" /> Back to overview</button><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow text-[hsl(var(--accent))]">BE-FAC-2026-001</p><h2 className="display mt-2 text-3xl font-extrabold tracking-[-.04em] text-[hsl(var(--primary))]">Factory Licence</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Industries Department · submitted 24 Aug 2026</p></div><StatusPill status={decision === 'Approved' ? 'Approved' : query.status === 'Responded' ? 'In progress' : 'Documents required'} /></div><div className="mt-8 grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Journey timeline</p><h3 className="display mt-2 text-xl font-extrabold text-[hsl(var(--primary))]">Where things stand</h3></div><span className="rounded-full bg-[hsl(var(--secondary)/.3)] px-2.5 py-1 text-[11px] font-bold text-[hsl(var(--primary))]">In review</span></div><div className="mt-8 space-y-0">{[['Application submitted', '24 Aug 2026', true, 'Your application was received by the Industries Department.'], ['Documents reviewed', '30 Aug 2026', true, '7 of 8 documents matched the expected format.'], ['Clarification requested', '14 Sep 2026', query.status === 'Responded', query.status === 'Responded' ? 'Your response was submitted for review.' : 'The officer needs one clarification before continuing.'], ['Decision', decision === 'Approved' ? 'Approved' : 'Pending', decision === 'Approved', decision === 'Approved' ? 'The Industries Department approved your Factory Licence.' : 'A decision follows once the clarification is reviewed.']].map(([title, date, done, copy], index) => <div key={String(title)} className="relative flex gap-4 pb-8 last:pb-0"><div className={`relative z-10 grid h-9 w-9 shrink-0 place-items-center rounded-full ${done ? 'bg-[hsl(var(--chart-4))] text-white' : 'border-2 border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--muted-foreground))]'}`}>{done ? <Check className="h-4 w-4" /> : index + 1}{index < 3 && <span className={`absolute left-1/2 top-9 h-8 w-px ${done ? 'bg-[hsl(var(--chart-4)/.45)]' : 'bg-[hsl(var(--border))]'}`} />}</div><div><div className="flex flex-wrap items-center gap-2"><h4 className="text-sm font-bold text-[hsl(var(--primary))]">{String(title)}</h4><span className="text-xs text-[hsl(var(--muted-foreground))]">{String(date)}</span></div><p className="mt-1 text-xs leading-5 text-[hsl(var(--muted-foreground))]">{String(copy)}</p></div></div>)}</div></section><div className="space-y-6"><section className={`rounded-2xl border p-5 sm:p-7 ${query.status === 'Responded' ? 'border-[hsl(var(--chart-4)/.3)] bg-[hsl(var(--chart-4)/.07)]' : 'border-[hsl(var(--accent)/.3)] bg-[hsl(var(--accent)/.07)]'}`}><div className="flex gap-4"><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${query.status === 'Responded' ? 'bg-[hsl(var(--chart-4))] text-white' : 'bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]'}`}>{query.status === 'Responded' ? <CheckCircle2 /> : <CircleAlert />}</span><div><p className="eyebrow" style={{ color: query.status === 'Responded' ? 'hsl(var(--chart-4))' : 'hsl(var(--accent))' }}>{query.status === 'Responded' ? 'Response submitted' : 'Action required'}</p><h3 className="display mt-2 text-lg font-extrabold text-[hsl(var(--primary))]">{query.status === 'Responded' ? 'Clarification sent to the officer' : 'Clarification regarding factory layout'}</h3><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{query.message}</p></div></div>{query.status === 'Responded' ? <div className="mt-5 rounded-xl bg-[hsl(var(--card))] p-3 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><b className="text-[hsl(var(--primary))]">Your response:</b> {query.response}</div> : <div className="mt-5 flex items-center justify-between gap-3"><span className="text-xs font-bold text-[hsl(var(--accent))]">Due in 2 days</span><Button variant="danger" onClick={() => setShowModal(true)} data-testid="button-open-query-response">Respond to query <ArrowRight className="ml-2 h-4 w-4" /></Button></div>}</section><section className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="flex gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[hsl(var(--secondary)/.3)] text-[hsl(var(--primary))]"><MapPin /></span><div><p className="eyebrow text-[hsl(var(--muted-foreground))]">Next on the route</p><h3 className="display mt-2 text-lg font-extrabold text-[hsl(var(--primary))]">Factory premises inspection</h3><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">28 September 2026 · Chhatrapati Sambhajinagar</p><span className="mt-4 inline-flex rounded-full bg-[hsl(var(--secondary)/.3)] px-2.5 py-1 text-[11px] font-bold text-[hsl(var(--primary))]">Scheduled</span></div></div></section></div></div></div>{showModal && <div className="fixed inset-0 z-50 grid place-items-center bg-[hsl(var(--foreground)/.3)] p-5"><div className="w-full max-w-lg rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="eyebrow text-[hsl(var(--accent))]">Respond to query</p><h3 className="display mt-2 text-2xl font-extrabold text-[hsl(var(--primary))]">Add your clarification</h3></div><button onClick={() => setShowModal(false)} className="rounded-lg p-2 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]" data-testid="button-close-query-modal"><X className="h-4 w-4" /></button></div><p className="mt-5 rounded-xl bg-[hsl(var(--muted)/.6)] p-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Please provide clarification regarding the factory layout, specifically the separation between the processing line and the proposed storage area.</p><label className="mt-5 block text-sm font-bold text-[hsl(var(--primary))]">Your response<textarea value={response} onChange={(event) => setResponse(event.target.value)} rows={5} placeholder="Explain the separation and any safety measures..." className="mt-2 w-full resize-none rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] p-3 text-sm outline-none focus:border-[hsl(var(--primary))]" data-testid="textarea-query-response" /></label><label className="mt-4 flex cursor-pointer items-center gap-2 rounded-xl border border-dashed border-[hsl(var(--border))] p-3 text-xs font-bold text-[hsl(var(--muted-foreground))]"><Paperclip className="h-4 w-4" />{fileName || 'Attach an optional supporting file'}<input type="file" className="hidden" accept=".pdf,.jpg,.jpeg,.png" onChange={(event) => setFileName(event.target.files?.[0]?.name || '')} data-testid="input-query-attachment" /></label><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setShowModal(false)} data-testid="button-cancel-query">Cancel</Button><Button onClick={submitResponse} disabled={!response.trim()} data-testid="button-submit-query">Submit response <Check className="ml-2 h-4 w-4" /></Button></div></div></div>}</AppShell>;
}

export function NotFound() { const [, setLocation] = useLocation(); return <div className="grid min-h-[100dvh] place-items-center bg-[hsl(var(--background))] p-5"><div className="text-center"><Logo /><h1 className="display mt-12 text-5xl font-extrabold text-[hsl(var(--primary))]">Page not found</h1><p className="mt-3 text-sm text-[hsl(var(--muted-foreground))]">That route is not part of this journey.</p><Button className="mt-7" onClick={() => setLocation('/')} data-testid="button-not-found-home">Back to BizVia</Button></div></div>; }
